"use client";
import { usePremiumUpgrade } from "@/components/premium-upgrade-provider";
import { Target } from "lucide-react";
import { Feedback } from "@/components/forms";
import {
  commonRoles,
  isPresetRole,
  normalizeRole,
  roleShortcutHelp,
} from "@/lib/roles";
import { useRoleSuggestions } from "@/components/role-allowance";
import { useRolePreferences } from "@/components/use-role-preferences";
import { SettingsPanel } from "./SettingsPanel";
import { RoleChip } from "./RoleChip";
import { SavedStatus } from "./SavedStatus";
import styles from "./settings.module.css";

export function OutreachPreferences({ roles }: { roles: string[] }) {
  const upgrade = usePremiumUpgrade();
  const { inputRef, ...draft } = useRolePreferences(roles);
  const { list, suggestions } = useRoleSuggestions();
  const displayed = [
    ...commonRoles,
    ...draft.values.filter((role) => !isPresetRole(role)),
  ];
  return (
    <SettingsPanel
      id="outreach"
      title="Outreach preferences"
      icon={Target}
      description={roleShortcutHelp(draft.plan)}
    >
      <div
        className="flex flex-wrap gap-2.5"
        role="group"
        aria-label="Role shortcuts"
      >
        {displayed.map((role) => {
          const selected = draft.values.find(
            (value) => normalizeRole(value) === normalizeRole(role),
          );
          return (
            <div key={role} className="flex max-w-full items-center gap-1">
              <RoleChip
                role={selected ?? role}
                selected={selected !== undefined}
                disabled={
                  draft.pending ||
                  (!selected && draft.atLimit && draft.plan !== "FREE")
                }
                onClick={() => {
                  if (!selected && draft.atLimit && draft.plan === "FREE")
                    return upgrade({ feature: "role-shortcuts" });
                  draft.toggle(selected ?? role);
                }}
              />
              {selected !== undefined && (
                <button
                  type="button"
                  className="min-h-11 py-0 px-2 text-[13px] text-[var(--settings-text)] underline cursor-pointer css-hover:text-[var(--settings-pink)] css-hover:[text-decoration-thickness:2px]"
                  aria-label={`Edit ${selected}`}
                  disabled={draft.pending}
                  onClick={() => draft.edit(selected)}
                >
                  Edit
                </button>
              )}
            </div>
          );
        })}
      </div>
      <p
        className="mt-3.5 text-[13px] text-[var(--settings-muted)]"
        aria-live="polite"
      >
        {draft.values.length} of {draft.limit} roles selected
        {draft.atLimit ? " · maximum reached" : ""}
      </p>
      <form
        onSubmit={(event) => {
          event.preventDefault();
          if (
            draft.plan === "FREE" &&
            draft.atLimit &&
            draft.editing === null &&
            draft.custom.trim()
          )
            return upgrade({ feature: "role-shortcuts" });
          draft.save();
        }}
      >
        <label
          htmlFor="custom-role"
          className="block text-[14px] font-semibold [margin:24px_0_8px]"
        >
          Custom role
        </label>
        {draft.editing !== null && (
          <p className="mb-2 text-sm text-body">Editing {draft.editing}</p>
        )}
        <div
          className={`flex items-stretch gap-2.5 [@media(max-width:_600px)]:flex-col`}
        >
          <input
            ref={inputRef}
            id="custom-role"
            className={`placeholder:text-[var(--settings-muted)] h-11.5 max-w-full rounded-[var(--appearance-radius,_14px)] [border:1px_solid_var(--settings-border)] [background:var(--settings-inset)] py-0 px-4 text-[var(--settings-text)] text-[14px] min-w-0 flex-1 [@media(max-width:_600px)]:flex-auto`}
            type="text"
            name="customRole"
            list={list}
            placeholder="e.g. Platform Engineer"
            value={draft.custom}
            maxLength={160}
            autoComplete="off"
            disabled={draft.pending}
            aria-invalid={!!draft.error}
            aria-describedby={`preference-role-help${draft.error ? " preference-role-error" : ""}`}
            onChange={(event) => draft.change(event.target.value)}
            onKeyDown=[REDACTED_SECRET]
              if (event.key === "Escape" && draft.editing !== null) {
                event.preventDefault();
                draft.cancel();
              }
            }}
          />
          <button
            className={`${styles.secondary} secondary-button h-11.5 shrink-0 inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer button-interaction [border:1px_solid_var(--settings-strong)] text-[var(--settings-text)] [background:transparent] shadow-[var(--appearance-shadow,_none)]`}
            type="button"
            disabled={
              draft.pending ||
              (draft.editing === null && draft.atLimit && draft.plan !== "FREE")
            }
            onClick={() => {
              if (
                draft.editing === null &&
                draft.atLimit &&
                draft.plan === "FREE"
              )
                return upgrade({ feature: "role-shortcuts" });
              draft.add();
            }}
          >
            {draft.editing !== null ? "Update role" : "Add role"}
          </button>
          {draft.editing !== null && (
            <button
              className={`${styles.secondary} secondary-button inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer button-interaction [border:1px_solid_var(--settings-strong)] text-[var(--settings-text)] [background:transparent] shadow-[var(--appearance-shadow,_none)]`}
              type="button"
              disabled={draft.pending}
              onClick={draft.cancel}
            >
              Cancel
            </button>
          )}
        </div>
        <p id="preference-role-help" className="mt-2 text-xs text-body">
          {draft.values.length > draft.limit
            ? `Remove roles until ${draft.limit} remain before replacing a role.`
            : "To replace a role, choose Edit or remove it and add another."}
        </p>
        {draft.error && (
          <p
            id="preference-role-error"
            role="alert"
            className="mt-2 text-xs text-error-deep"
          >
            {draft.error}
          </p>
        )}
        {suggestions}
        {draft.result?.ok === false && (
          <Feedback result={draft.result} inlineFieldErrors />
        )}
        <div className="flex flex-wrap items-center gap-3.5 mt-6">
          <button
            type="submit"
            className={`${styles.primary} inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer button-interaction primary-action [background:var(--primary-action-gradient)] text-[var(--primary-action-ink)] shadow-none [border:1px_solid_transparent] text-[var(--primary-action-ink)] [background:var(--primary-action-gradient)] shadow-none`}
            disabled={draft.pending}
          >
            {draft.pending ? "Saving…" : "Save preferences"}
          </button>
          <SavedStatus result={draft.result} />
        </div>
      </form>
    </SettingsPanel>
  );
}
